 [37,
  '_vistas_colgadas',
  'INSERT INTO _vistas_colgadas (orden, vista, definicion, opciones, comentario, permisos)\n'
  '        WITH RECURSIVE arbol AS (\n'
  '            SELECT c.oid, c.relname::TEXT AS vista, 0 AS nivel\n'
  '              FROM pg_class c\n'
  "             WHERE c.relname = v_vista AND c.relkind = 'v'\n"
  '            UNION ALL\n'
  '            SELECT dep.oid, dep.relname::TEXT, a.nivel + 1\n'
  '              FROM arbol a\n'
  '              JOIN pg_depend d   ON d.refobjid = a.oid\n'
  '              JOIN pg_rewrite rw ON rw.oid = d.objid\n'
  "              JOIN pg_class dep  ON dep.oid = rw.ev_class AND dep.relkind = 'v'\n"
  '             WHERE dep.oid <> a.oid\n'
  '               AND a.nivel < 10          \n'
  '        )\n'
  '        SELECT\n'
  '            MAX(a.nivel),\n'
  '            a.vista,\n'
  '            pg_get_viewdef(a.oid, true),\n'
  "            (SELECT array_to_string(c.reloptions, ', ') FROM pg_class c WHERE c.oid = a.oid),\n"
  "            obj_description(a.oid, 'pg_class'),\n"
  "            (SELECT jsonb_agg(jsonb_build_object('quien', g.grantee, 'que', g.privilege_type))\n"
  '               FROM information_schema.role_table_grants g\n'
  "              WHERE g.table_schema = 'public'\n"
  '                AND g.table_name = a.vista\n'
  '                AND g.grantee <> CURRENT_USER)\n'
  '          FROM arbol a\n'
  '         GROUP BY a.oid, a.vista'],
